"""Append-only local JSON ledger for forecasts generated by trusted orchestration."""

from contextlib import contextmanager
import json
import math
import os
from pathlib import Path
import re
import tempfile
from uuid import uuid4

from scripts.inference.common import InferenceError
from scripts.prepare_training_features import FEATURES
from .acquire import LOCAL
from .composite_history import RESEARCH_ROOT, dumps
from .forecast_eligibility import MODE, READY, utc
from .forecast_generation import PARITY_TOLERANCE, SCHEMA_VERSION
from .match_registry import require, semantic_hash

FORECAST_ROOT = LOCAL / "forecasts"
_HEX = re.compile(r"[0-9a-f]{64}")
_ID = re.compile(r"[0-9a-f]{32}")


def _validate_prediction(record):
    features = record["features"]
    require(features["order"] == list(FEATURES)
            and all(len(features[side]) == len(FEATURES) and all(
                value is None or type(value) in (int,float) and math.isfinite(value)
                for value in features[side]) for side in ("home","away"))
            and semantic_hash(features) == record["features_sha256"],
            "INVALID_FEATURES", "Forecast features do not match the ordered feature contract")
    raw = record["raw_predictions"]
    require(len(raw) == 2 and all(type(value) in (int,float) and math.isfinite(value) for value in raw)
            and record["home_xg"] == max(0,raw[0]) and record["away_xg"] == max(0,raw[1]),
            "INVALID_PREDICTION", "Forecast xG and raw predictions are inconsistent")


def _same_target(a, b):
    fields = ("canonical_fixture_key","target_match_date","target_kickoff_utc","target_semantics")
    return all(a[name] == b[name] for name in fields)


def _equal_inputs(a, b):
    return (_same_target(a,b) and a["model_artifact_sha256"] == b["model_artifact_sha256"]
            and a["features"] == b["features"])


def _prediction_parity(a, b):
    old = [*a["raw_predictions"], a["home_xg"], a["away_xg"]]
    new = [*b["raw_predictions"], b["home_xg"], b["away_xg"]]
    require(all(abs(x-y) <= PARITY_TOLERANCE for x,y in zip(old,new)),
            "FORECAST_PARITY_FAILED", "Equal model inputs disagree on raw or clipped xG")


class ForecastLedger:
    """A local writer lock plus exclusive atomic publication on the same filesystem."""

    def __init__(self, *, synthetic_base=None):
        self.kind = "real" if synthetic_base is None else "synthetic"
        if synthetic_base is None:
            self.root = FORECAST_ROOT / "real"
        else:
            base = Path(synthetic_base).resolve()
            real = (FORECAST_ROOT / "real").resolve()
            history = RESEARCH_ROOT.resolve()
            require(not any(base.is_relative_to(p) or p.is_relative_to(base) for p in (real,history)),
                    "INVALID_SCOPE", "Synthetic ledger must be isolated from real records and history")
            self.root = base / "synthetic"
        self.directory = self.root / "records"
        self._check_paths()

    def _check_paths(self):
        require(self.root.resolve() == self.root and self.directory.resolve() == self.directory
                and not self.directory.is_relative_to(RESEARCH_ROOT.resolve()),
                "INVALID_SCOPE", "Forecast records require a separate direct directory")

    def _validate(self, record):
        kind = record["dataset_kind"]
        require(kind == self.kind and ((kind == "synthetic" and record.get("demo_label") == "SYNTHETIC_DEMO")
                or (kind == "real" and "demo_label" not in record)),
                "INVALID_SCOPE", "Forecast dataset kind does not match ledger")
        require(record["schema_version"] == SCHEMA_VERSION and record["inference_mode"] == MODE
                and record["production_approved"] is False and record["eligibility_status"] in READY,
                "INVALID_FORECAST", "Only successful research forecasts can be persisted")
        now = utc(record["generated_at_utc"])
        kickoff = utc(record["target_kickoff_utc"])
        as_of, day = now.date().isoformat(), kickoff.date().isoformat()
        require(record["forecast_as_of_date"] == as_of and record["target_match_date"] == day
                and record["history_cutoff"] == min(as_of,day) and now < kickoff,
                "INVALID_FORECAST", "Inconsistent forecast cutoff or kickoff")
        require(all(isinstance(record[key],str) and _HEX.fullmatch(record[key])
                    for key in ("history_database_sha256","model_artifact_sha256")),
                "INVALID_FORECAST", "Forecast requires snapshot and model checksums")
        _validate_prediction(record)

    def _read(self, path):
        try:
            require(path.resolve() == path, "LEDGER_CORRUPT", "Forecast path is redirected")
            data = json.loads(path.read_text(encoding="utf-8"))
            content = {k:v for k,v in data.items() if k != "record_sha256"}
            require(path.stem == data["forecast_id"] and _ID.fullmatch(path.stem)
                    and data["record_sha256"] == semantic_hash(content),
                    "LEDGER_CORRUPT", "Forecast identifier or checksum does not match")
            self._validate(data)
            return data
        except (OSError, ValueError, TypeError, KeyError, AttributeError) as exc:
            raise InferenceError("LEDGER_CORRUPT", "Unreadable or invalid forecast record") from exc

    def _records(self):
        self._check_paths()
        grouped = {}
        for path in self.directory.glob("*.json"):
            record = self._read(path)
            grouped.setdefault(record["canonical_fixture_key"],[]).append(record)
        for chain in grouped.values():
            require(all(type(row["forecast_revision"]) is int for row in chain),
                    "LEDGER_CORRUPT", "Invalid forecast revision")
            chain.sort(key=lambda row:row["forecast_revision"])
            previous = None
            for revision,row in enumerate(chain,1):
                require(row["forecast_revision"] == revision
                        and row["previous_forecast_id"] == (previous["forecast_id"] if previous else None)
                        and row["forecast_stage"] == ("UPDATED" if previous else "INITIAL")
                        and (previous is None or utc(row["generated_at_utc"]) >= utc(previous["generated_at_utc"])),
                        "LEDGER_CORRUPT", "Broken forecast revision lineage")
                previous = row
        return grouped

    def list_fixture_forecasts(self, canonical_fixture_key):
        return self._records().get(canonical_fixture_key,[])

    def get_forecast(self, forecast_id):
        require(isinstance(forecast_id,str) and _ID.fullmatch(forecast_id),
                "INVALID_FORECAST_ID", "Use an opaque forecast identifier")
        for chain in self._records().values():
            for row in chain:
                if row["forecast_id"] == forecast_id:
                    return row
        raise InferenceError("FORECAST_NOT_FOUND", "Forecast is absent from this namespace")

    @contextmanager
    def _writer(self):
        self._check_paths()
        self.directory.mkdir(parents=True,exist_ok=True)
        lock = self.root / ".writer.lock"
        try:
            fd = os.open(lock,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
        except FileExistsError as exc:
            raise InferenceError("LEDGER_BUSY", "A writer already owns the forecast ledger") from exc
        try:
            yield
        finally:
            os.close(fd)
            lock.unlink()

    def _publish_record(self, record):
        destination = self.directory / (record["forecast_id"]+".json")
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(dir=self.directory,suffix=".tmp",delete=False) as stream:
                temporary = Path(stream.name)
                stream.write((dumps(record)+"\n").encode("utf-8"))
                stream.flush()
                os.fsync(stream.fileno())
            # Atomic creation, with no replace even if a destination already exists.
            os.link(temporary,destination)
        finally:
            if temporary is not None:
                temporary.unlink()

    def append(self, candidate, *, expected_previous_id):
        """Accept only trusted generated candidates. The expected ID provides compare-and-swap."""
        authoritative = {"forecast_id","forecast_revision","previous_forecast_id","forecast_stage","record_sha256"}
        require(not authoritative.intersection(candidate), "INVALID_FORECAST", "Ledger owns revision fields")
        self._validate(candidate)
        key = candidate["canonical_fixture_key"]
        with self._writer():
            chain = self.list_fixture_forecasts(key)
            previous = chain[-1] if chain else None
            previous_id = previous["forecast_id"] if previous else None
            require(expected_previous_id == previous_id, "STALE_FORECAST_WRITE", "Latest forecast changed")
            if previous is not None:
                require(utc(candidate["generated_at_utc"]) >= utc(previous["generated_at_utc"]),
                        "STALE_FORECAST_WRITE", "Forecast predates the latest revision")
                for old in reversed(chain):
                    if _equal_inputs(old,candidate):
                        _prediction_parity(old,candidate)
                if _equal_inputs(previous,candidate):
                    return dict(status="NO_CHANGE",forecast_id=previous_id,forecast=previous)
            record = dict(candidate,forecast_id=uuid4().hex,forecast_revision=len(chain)+1,
                          previous_forecast_id=previous_id,forecast_stage="UPDATED" if previous else "INITIAL")
            record["record_sha256"] = semantic_hash(record)
            self._publish_record(record)
            return dict(status="PUBLISHED",forecast_id=record["forecast_id"],forecast=record)

    def compare_forecasts(self, fixture_key, forecast_v1_id, forecast_v2_id):
        chain = self.list_fixture_forecasts(fixture_key)
        records = {row["forecast_id"]:row for row in chain}
        require(forecast_v1_id in records and forecast_v2_id in records,
                "INCOMPATIBLE_FORECASTS", "Forecasts must share the fixture and dataset namespace")
        a,b = records[forecast_v1_id],records[forecast_v2_id]
        require(a["forecast_revision"] < b["forecast_revision"]
                and a["target_semantics"] == b["target_semantics"]
                and a["feature_schema_version"] == b["feature_schema_version"],
                "INCOMPATIBLE_FORECASTS", "Use two revisions in lineage order with comparable feature and target definitions")
        changed, unchanged = [], []
        for i,name in enumerate(FEATURES):
            before = [a["features"][side][i] for side in ("home","away")]
            after = [b["features"][side][i] for side in ("home","away")]
            if before != after:
                changed.append(dict(feature=name,before=before,after=after))
            else:
                unchanged.append(name)
        result = dict(fixture_key=fixture_key,forecast_v1_id=forecast_v1_id,forecast_v2_id=forecast_v2_id,
                      dataset_kind=self.kind,schedule_notice=None if _same_target(a,b) else "SCHEDULE_REVISED",
                      changed_features=changed,unchanged_features=unchanged,
                      history_cutoff_before=a["history_cutoff"],history_cutoff_after=b["history_cutoff"],
                      snapshot_before=a["history_snapshot_version"],snapshot_after=b["history_snapshot_version"],
                      history_window_changes=dict(before=a["history_windows"],after=b["history_windows"]),
                      history_provenance_changes=dict(before=a["history_provenance"],after=b["history_provenance"]),
                      production_approved=False)
        if self.kind == "synthetic":
            result["demo_label"] = "SYNTHETIC_DEMO"
        for side in ("home","away"):
            field = side+"_xg"
            result.update({field+"_before":a[field],field+"_after":b[field],field+"_delta":b[field]-a[field]})
        return result
